record.field:
records = model.browse(env.context.get('active_ids', []))
eligible = records.filtered(
    lambda obligation: obligation.state in ('pending', 'overdue')
)
skipped = len(records) - len(eligible)
eligible.action_mark_paid()
message = 'Se marcaron %s obligación(es) como pagadas.' % len(eligible)
if skipped:
    message += ' %s quedaron fuera por su estado.' % skipped
action = {
    'type': 'ir.actions.client',
    'tag': 'display_notification',
    'params': {
        'type': 'success' if eligible else 'warning',
        'message': message,
        'sticky': False,
        'next': {'type': 'ir.actions.client', 'tag': 'soft_reload'},
    },
}

records = model.browse(env.context.get('active_ids', []))
eligible = records.filtered(
    lambda obligation: not obligation.due_date_override
    and obligation.state != 'paid'
)
eligible.action_recalculate_due_dates()
skipped = len(records) - len(eligible)
message = 'Se recalcularon %s vencimiento(s).' % len(eligible)
if skipped:
    message += ' %s quedaron fuera (vencimiento manual o pagadas).' % skipped
action = {
    'type': 'ir.actions.client',
    'tag': 'display_notification',
    'params': {
        'type': 'success' if eligible else 'warning',
        'message': message,
        'sticky': False,
        'next': {'type': 'ir.actions.client', 'tag': 'soft_reload'},
    },
}
